Connecting local origins with','about-hero-title-2':'global opportunity.','about-lead':'Bakoel Rempah connects quality products from Indonesian farmers and trusted partners with buyers and industries around the world. We believe every strong trade connection begins with understanding the people, products, and places behind it.','about-story-eyebrow':'Who we are','about-story-title':'From Aceh, with a wider view.','about-story-text-1':'We build dependable connections between Indonesian producers and the right partners in international markets.','about-story-text-2':'Through thoughtful coordination, clear communication, and trusted relationships, we help good products move forward with confidence.','vision-title':'Our vision','vision-text':'To be a trusted bridge for Indonesian products, helping local potential reach responsible markets around the world.','mission-title':'Our mission','mission-text':'We connect quality products with the right partners through reliable service, transparent communication, and trade that creates lasting value.','values-title':'Our values','values-text':'Integrity in every conversation, consistency in every process, collaboration with every partner, and respect for every origin.','commitment-title':'Our commitment','commitment-text':'We listen carefully, communicate clearly, and stay involved from the first inquiry until the next step is understood by everyone.','about-button':'Start a conversation'}};function applyLanguage(lang){const data=translations[lang]||translations.id;Object.entries(data).forEach(([key,value])=>{const el=document.getElementById(key);if(el)el.textContent=value;});document.documentElement.lang=lang;document.querySelectorAll('.lang-btn').forEach((button)=>button.classList.toggle('is-active',button.dataset.lang===lang));localStorage.setItem('lang',lang);}document.querySelectorAll('.lang-btn').forEach((button)=>button.addEventListener('click',()=>applyLanguage(button.dataset.lang)));applyLanguage(localStorage.getItem('lang')||'id');</script>
<script>
	(() => {
		const brandName = 'Serambi bakul rempah';
		const replaceBrand = () => {
			document.title = document.title.replace(/Bakoel Rempah/gi, brandName);
			document.querySelectorAll('meta[content], img[alt]').forEach((element) => {
				const attribute = element.hasAttribute('content') ? 'content' : 'alt';
				element.setAttribute(attribute, element.getAttribute(attribute).replace(/Bakoel Rempah/gi, brandName));
			});
			const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
			while (walker.nextNode()) if (/Bakoel Rempah/i.test(walker.currentNode.nodeValue)) walker.currentNode.nodeValue = walker.currentNode.nodeValue.replace(/Bakoel Rempah/gi, brandName);
		};
		replaceBrand();
		new MutationObserver(replaceBrand).observe(document.body, { childList: true, subtree: true, characterData: true });
	})();
</script>
